/** Builds the default flow for a new project (CLAUDE.md section 5). Pure: ids are generated by the caller's `newId`. */
import { DEFAULT_FLOW } from './flow';
import { dependencySchedule, happyCase } from './schedule';
import type { Environment, Member, Role, Task } from './types';

export interface FlowBuildResult {
  tasks: Task[];
  /** Default client commits from the happy case (section 5). Prod uses the entered date. */
  commitUat: string | null;
  commitStg: string | null;
}

/**
 * Creates the 13-step flow.
 * - Each task is blocked by all tasks of the previous step.
 * - PIC: first project member with the matching role, otherwise null.
 * - Deadline: planned finish of the task (dependency schedule).
 * - Codes: T01, T02, ... in flow order.
 */
export function buildDefaultFlow(opts: {
  startIso: string;
  today: string;
  members: Member[];
  newId: () => string;
}): FlowBuildResult {
  const tasks: Task[] = [];
  let previousStep: string[] = [];
  let seq = 0;

  for (const step of DEFAULT_FLOW) {
    const thisStep: string[] = [];
    for (const tpl of step.tasks) {
      seq += 1;
      const id = opts.newId();
      const pic = opts.members.find((m) => m.role === tpl.role) ?? null;
      tasks.push({
        id,
        projectId: '',
        code: `T${String(seq).padStart(2, '0')}`,
        name: tpl.name,
        phase: step.phase,
        environment: step.environment as Environment,
        role: tpl.role as Role,
        picId: pic?.id ?? null,
        status: 'todo',
        duration: tpl.duration,
        deadline: opts.startIso, // set below from the schedule
        blockedBy: [...previousStep],
        blocked: false,
        blocker: '',
        description: '',
        sinceDate: opts.today,
        alerts: [],
        sortOrder: seq,
        outputs: [],
      });
      thisStep.push(id);
    }
    previousStep = thisStep;
  }

  // Deadlines = planned finish of each task
  const plan = dependencySchedule(tasks, opts.startIso);
  for (const t of tasks) t.deadline = plan.plans.get(t.id)?.end ?? opts.startIso;

  // Default commits from the happy case of the flow (Prod uses the entered date)
  const hc = happyCase(tasks, opts.startIso);
  const completionOf = (env: Environment) => hc.envs.find((e) => e.env === env)?.completion ?? null;

  return {
    tasks,
    commitUat: completionOf('UAT'),
    commitStg: completionOf('STG'),
  };
}
